def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    color = 3

    for r in range(h):
        cols = sorted(c for rr, c in points if rr == r)
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = color

    for c in range(w):
        rows = sorted(r for r, cc in points if cc == c)
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = color
    return out
